course_grade &lt;- function(ps = 0, projects = 0, quizzes = 0, final_exam = 0,
                         ps_w = .05, projects_w = .15, quizzes_w = .5, final_exam_w = .3) {
  grade &lt;- ps_w * mean(ps) + projects_w * mean(projects) + 
    quizzes_w * mean(quizzes) + final_exam_w * final_exam
  return(grade)
}




